async function resolveMembership(user:{userId:string;email?:string;name?:string}){
  const email=norm(user.email);if(!email)return null;
  const items=await findAccess(email);const ownerPreferred=email===ownerEmail()?(items.find(m=>m.canonicalOwner&&m.userId===user.userId)||items.find(m=>m.canonicalOwner)):undefined;const current=ownerPreferred||items.find(m=>m.userId===user.userId)||items[0];if(!current)return null;
  if(current.userId!==user.userId||current.name!==user.name){const firstBind=!current.userId,stamp=now(),next={...current,userId:user.userId,name:user.name||current.name,joinCode:firstBind?undefined:current.joinCode,claimedAt:firstBind?stamp:current.claimedAt,updatedAt:stamp};await db.update(accessTable(email),[{id:current.id,record:next as Record<string,unknown>}]);if(current.projectMemberId){const [pm]=await db.get<Member>(membersTable(current.projectId),[current.projectMemberId]);if(pm)await db.update(membersTable(current.projectId),[{id:current.projectMemberId,record:{...pm,userId:user.userId,name:user.name||pm.name,joinCode:firstBind?undefined:pm.joinCode,claimedAt:firstBind?stamp:pm.claimedAt,updatedAt:stamp} as Record<string,unknown>}])}if(firstBind&&current.joinCode){const invite=await db.list<Record<string,unknown>>(inviteTable(current.joinCode),{limit:1});if(invite.items[0])await db.delete(inviteTable(current.joinCode),[invite.items[0].id])}return{...next,id:current.id}}
  return current;
}
async function ensureOwnerMembership(user:{userId:string;email?:string;name?:string}){if(norm(user.email)!==ownerEmail())return null;const companies=(await db.list<Record<string,unknown>>('companies',{limit:100})).items;let companyId=companies.find(c=>norm(String(c.name||''))===norm(ownerCompany()))?.id;if(!companyId){const [created]=await db.add('companies',[{name:ownerCompany(),createdAt:now(),createdBy:user.userId}]);companyId=created||undefined}if(!companyId)throw new Error('Falha ao preparar empresa do proprietário');const projects=(await db.list<Project>('projects',{limit:100})).items;let projectId=projects.find(p=>p.companyId===companyId&&norm(p.name)===norm(ownerProject()))?.id;if(!projectId){const record:Project={companyId,name:ownerProject(),customer:ownerCustomer(),createdAt:now(),createdBy:user.userId};const [created]=await db.add('projects',[record as unknown as Record<string,unknown>]);projectId=created||undefined}if(!projectId)throw new Error('Falha ao preparar obra do proprietário');const member=await upsertMember(projectId,companyId,{email:ownerEmail(),role:'admin'}),stamp=now(),memberId=String(member.id),canonical={...member,canonicalOwner:true,userId:user.userId,name:user.name||member.name,joinCode:undefined,claimedAt:member.claimedAt||stamp,updatedAt:stamp};await db.update(membersTable(projectId),[{id:memberId,record:canonical as unknown as Record<string,unknown>}]);const accesses=await findAccess(ownerEmail()),access=accesses.find(a=>a.projectId===projectId);if(access)await db.update(accessTable(ownerEmail()),[{id:access.id,record:{...access,...canonical,projectMemberId:memberId} as unknown as Record<string,unknown>}]);const resolved=await resolveMembership(user);if(resolved)await audit(resolved,user,'owner_auto_provisioned',{companyName:ownerCompany(),projectName:ownerProject()});return resolved}
