async function requireMember(user:{userId:string;email?:string;name?:string},roles?:Role[],channel='mobile',module?:string){
  const member=await resolveMembership(user);if(!member)return{member:null,access:null,response:error('Acesso ainda não configurado para esta conta.',403)};
  const project=await getProject(member.projectId);if(!project||project.companyId!==member.companyId)return{member,access:null,response:error('Vínculo entre empresa e obra inconsistente.',403)};
  const platform=await getPlatformAccess(user.email||'');
  if(platform&&platform.status!=='active')return{member,access:null,response:error(platform.status==='blocked'?'Usuário bloqueado. A sessão foi revogada.':'Use sua credencial provisória em Meus sistemas para ativar o acesso.',403)};
  if(platform&&platform.platformRole!=='superadmin'&&(!(platform.companyIds||[]).includes(member.companyId)||!(platform.projectIds||[]).includes(member.projectId)))return{member,access:null,response:error('A credencial não pertence a esta empresa/obra.',403)};
  if(module==='obra360'&&platform&&!platform.systems.obra360.enabled)return{member,access:null,response:error('Obra360 não está liberado para esta credencial.',403)};
  if(roles&&!roles.includes(member.role))return{member,access:null,response:error('Acesso não permitido para este perfil.',403)};
  const access=await memberEntitlements(member);if(!access.channels.includes(channel))return{member,access,response:error(`Sua conta não possui acesso ${channel}.`,403)};if(module&&!access.modules.includes(module))return{member,access,response:error(`O módulo ${module} não está liberado para esta conta.`,403)};return{member,access,response:null}
}

async function requirePhoneField(token:string){
  const participant=await educationParticipantBySession(token);if(!participant)return{response:error('Sessão por celular expirada.',401)} as const;
  const phoneAccess=await getPhoneAccess(String(participant.phone||''));if(!phoneAccess||phoneAccess.status!=='active')return{response:error('Acesso de campo não configurado para este celular.',403)} as const;
  if(!phoneAccess.systems.obra360.enabled||phoneAccess.systems.obra360.role!=='encarregado')return{response:error('Obra na Mão não liberado como Encarregado.',403)} as const;
  if(participant.employeeId&&participant.employeeId!==phoneAccess.employeeId)return{response:error('Vínculo de funcionário inconsistente.',409)} as const;
  if(participant.companyId&&participant.companyId!==phoneAccess.companyId)return{response:error('Vínculo de empresa inconsistente.',409)} as const;
  const project=await getProject(phoneAccess.projectId);if(!project||project.companyId!==phoneAccess.companyId)return{response:error('Vínculo entre empresa e obra inconsistente.',409)} as const;
  const entitlement=await companyEntitlements(phoneAccess.companyId);if(!entitlement||!entitlement.channels.includes('mobile')||!entitlement.modules.includes('obra360'))return{response:error('A operação não possui Obra na Mão Mobile liberado.',403)} as const;
  return{participant,phoneAccess,access:{...entitlement,modules:intersect(entitlement.modules,['obra360','rdo']),channels:['mobile']}} as const;
}

